import {ToolRegistry} from './registry.js';

describe('ToolRegistry validation', () => {
  it('rejects input with a missing required property without calling executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;

    registry.register(
      {
        name: 'test_tool',
        description: 'Test tool',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'result';
      }
    );

    const response = await registry.execute('test_tool', {});

    expect({
      executorCalls,
      mentionsLocation: response.result.includes('location'),
    }).toEqual({
      executorCalls: 0,
      mentionsLocation: true,
    });
  });

  it('includes field name in type error message', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;

    registry.register(
      {
        name: 'test_type_error',
        description: 'Test tool',
        inputSchema: {
          type: 'object',
          properties: {ssn: {type: 'string'}},
          required: ['ssn'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'result';
      }
    );

    const response = await registry.execute('test_type_error', {ssn: 123456789});

    console.log('Error message:', response.result);
    expect(executorCalls).toBe(0);
    expect(response.result).toContain('ssn');
    expect(response.result).toContain('string');
    expect(response.result).not.toContain('123456789');
  });
});

